/// <summary>
/// Base rendering pipeline for GameZ.
/// </summary>
class CPipe
{
public:
	/// <summary>
	/// Handles transparency.
	/// </summary>
	/* port: the ELF has only the nested CPipe::CAlpha (Add__Q25CPipe6CAlpha..., m_first_alpha_add__Q25CPipe6CAlpha);
	   defined here, ahead of m_alpha, with the data members of the former global CAlpha */
	/* DWARF has only the declaration (CAlpha::m_visualList is a tag_DelayedNode*); the
	   112-byte layout is from CPipe::CAlpha::Add 0x241ff0 (stride 0x70) and Render 0x241d30 */
	struct tag_DelayedNode
	{
		CMatrix m_matrix;            /* +0x00 CStack::m_top at Add */
		f32 m_depth;                 /* +0x40 scaled view depth squared (1e8: vparams bit 18) */
		zdb::CVisual* m_visual;      /* +0x44 */
		u8 m_fov;                    /* +0x48 tag_ZVIS_FOV */
		zdb::CNode* m_atom;          /* +0x4c CPipe::m_node */
		zdb::CNode* m_node;          /* +0x50 */
		f32 m_addColor[3];           /* +0x54 CVisual::m_addColor */
		u16 m_lighting : 1;          /* +0x60 CVisual::m_lightingEnable */
		u16 m_fog : 1;               /* CVisual::m_fogEnable */
		u16 m_unk02 : 1;
		u16 m_vid : 13;              /* CVisual::m_stack_vid top */
		f32 m_opacity;               /* +0x64 */
		f32 m_globalLightScale;      /* +0x68 CVisual::m_GlobalLightScale */
		u32 m_unk6c;
	};

	class CAlpha
	{
		friend class CPipe;
	public:
		void Add(zdb::CNode *, zdb::CNode *, zdb::CVisual *, zdb::tag_ZVIS_FOV, float);
		void Render();
		static unsigned char m_first_alpha_add;
		static std::list<void*>::iterator m_last_alpha_insert; /* 4 bytes: the insertion hint (Add) */
	private:
		zdb::CCamera* m_camera;          /* DWARF CPipe::CAlpha (48 bytes) */
		tag_DelayedNode* m_visualList;   /* 2000 records (CPipe ctor) */
		tag_DelayedNode* m_next;
		std::list<void*> m_drawList;     /* records, farthest first */
		zdb::CDynTexList m_dyntexlist;
	};

	CPipe();

	static void Init();

	void RenderAtom(zdb::CNode* atomNode);
	void RenderNode(zdb::CNode* node, zdb::tag_ZVIS_FOV fov);
	void RenderUiNode(zdb::CNode* node);
	void RenderUiNodeRecursive(zdb::CNode* node);
	bool RenderVisual(zdb::CNode* node, zdb::tag_ZVIS_FOV fov);
	void RenderMesh(zdb::CNode* node, zdb::CMesh* mesh, CMatrix* mvp, zdb::tag_ZVIS_FOV fov);
	u32 RenderWorld(zdb::CWorld* world);
	void Flush();

	zdb::CCamera* m_camera;

	u32 m_texIntIdx;
	u32 m_texLoadIdx;

	zdb::tag_TexLoadCmds m_texLoadChain[128];

	zdb::CGSTexBuffer* m_assetAlpha;
	zdb::CGSTexBuffer* m_assetCommon;
	zdb::CGSTexBuffer* m_assetCharacter[2];
	zdb::CGSTexBuffer* m_assetHUD1;
	zdb::CGSTexBuffer* m_assetHUD2;
	zdb::CGSTexBuffer* m_assetHUDX;

	zdb::CWorld* m_world;
	zdb::CCell* m_cell;
	zdb::CNode* m_node;
	zdb::CTexture* m_lightmap;

	bool m_wireframe;
	bool m_terrain;
	bool m_polys;
	bool m_drawShadows;
	bool m_drawReflections;
	bool m_simpletrans;
	bool m_drawCharacters;
	bool m_doFog;
	bool m_doUI;
	bool m_drawDI;
	bool m_drawNormal;
	bool m_drawBBox;
	bool m_LODFilter;
	bool m_reticuleDraw;

	f32* m_opacity_stack;
	s32 m_opacity_stack_size;
	s32 m_opacity_stack_index;

	CAlpha m_alpha;

	std::vector<tag_DelayedNode> m_DelayedNodes; /* DWARF +0x684; SaveDelayedNode grows it by 8 (resize of
	                                                __vector_imp<15tag_DelayedNode>, 112-byte records) */
	u32 m_delayedNodeNum;
	/* @socom-skeleton decl 5CPipe */
public:
	~CPipe();
	void FIFO_Signal(zdb::CGSTexBuffer *, unsigned int *);
	void FIFO_Signal(zdb::CGSTexBuffer *);
	void Uninit();
	void BuildLightMapList(zdb::CNode *);
	void SaveDelayedNode(CMatrix *, zdb::CNode *, zdb::tag_ZVIS_FOV);
	void RenderDelayedNodes();
	void RenderNodeShadow(zdb::CNode *);
	void RenderMeshShadow(zdb::CNode *, zdb::CMesh *, CMatrix *);
	/* @socom-skeleton end 5CPipe */
};

